/*
 * Held — serial link from the audio "brain" ESP32 (held-electronics repo,
 * docs/Held_Lighting_Serial_Messages.md). Portable: it parses lines and drives the Engine; the
 * UART itself lives in held_wled.cpp. Tested natively by tools/held/link_test.cpp.
 *
 * Brain -> lighting, one ASCII line each, ending in '\n', fields separated by single spaces:
 *   BEAT <n> <bpm> <dub ms> <next ms>   every heartbeat, at the audible lub
 *   COUNT <seated> <required>           when the seated count changes, and once at brain startup
 *   STORY START <k>                     a story starts (proposed; optional)
 *   STORY END <k>                       the story finished playing
 *   PING                                answered with PONG
 * Anything else is ignored. Lighting -> brain: PONG, HELLO at startup, and a few LOG lines
 * (the brain echoes LOG lines to its Serial Monitor).
 *
 * What the lights do:
 *   BEAT       the heartbeat emits one pulse per BEAT (global beatSync), lub peak at the origin;
 *              with no BEAT for beatTimeout seconds the heartbeat's own BPM takes over again
 *   COUNT      sets the piece count (pieces are interchangeable: the lowest bits are set) and
 *              numPieces = required; the first COUNT after startup is adopted silently
 *   STORY START  plays the last-piece animation when allInTrigger = "Story start"
 *   STORY END    plays the storyEnd event
 */
#include "held_core.h"

namespace held {

constexpr int LINK_LINE_MAX  = 96;
constexpr int LINK_REPLY_MAX = 4;

struct LinkStatus {
  uint32_t lines;         // recognised lines
  uint32_t unknown;       // ignored lines (unknown, malformed or too long)
  uint32_t beats;         // BEATs received
  uint32_t missed;        // gaps in the BEAT counter
  uint32_t lastLineMs;    // time of the last line of any kind (0 = never)
  uint32_t lastBeatMs;
  uint32_t beatN;         // last BEAT counter value
  float bpm;
  uint16_t dubMs, nextMs;
  int8_t seated, required;  // -1 until a COUNT arrives
  uint16_t story;           // last story number (0 = none yet)
  bool storyPlaying;
  char last[LINK_LINE_MAX]; // last line received
};

class Link {
  public:
    explicit Link(Engine& e) : _e(e) { reset(); }
    void reset();
    void feed(char c, uint32_t nowMs);                    // bytes from the UART
    bool handleLine(const char* line, uint32_t nowMs);     // one complete line; true if recognised
    void poll(uint32_t nowMs);                            // beat timeout; call regularly
    bool popReply(char* out, size_t len);                 // next line to send back, if any
    void queueReply(const char* text);
    const LinkStatus& status() const { return _st; }

  private:
    Engine& _e;
    LinkStatus _st;
    char _buf[LINK_LINE_MAX];
    int _len;
    bool _overflow;
    bool _synced;          // a COUNT has been adopted since startup
    char _replies[LINK_REPLY_MAX][LINK_LINE_MAX];
    int _nReplies;
};

} // namespace held
